import { useEffect, useState } from 'react'
import { FlaskConical, RefreshCw, ShieldCheck } from 'lucide-react'

type Policy = { id:string; name:string; version?:number; enabled:boolean; priority:number; when:Record<string,unknown>; actions:Record<string,unknown> }
type Result = { actionId:string; current:{policyName:string;policyVersion:number;approvalRole:string;approvalCount:number;slaHours:number;escalationTargets:string[]}; proposed:{policyName:string;policyVersion:number;approvalRole:string;approvalCount:number;slaHours:number;escalationTargets:string[]}; impact:{approvalDelta:number;slaDeltaHours:number;escalationDelta:number;governanceImpact:string}; safeToPublish:boolean }
export function PolicySimulationPage(){const[policies,setPolicies]=useState<Policy[]>([]);const[actions,setActions]=useState<any[]>([]);const[selectedPolicy,setSelectedPolicy]=useState('critical');const[actionId,setActionId]=useState('');const[result,setResult]=useState<Result|null>(null);const[error,setError]=useState('');const token=localStorage.getItem('access_token')||'';const load=async()=>{try{setError('');const[p,a]=await Promise.all([fetch('/api/v1/assurance/policies',{headers:{Authorization:`Bearer ${token}`}}),fetch('/api/v1/assurance/actions',{headers:{Authorization:`Bearer ${token}`}})]);if(!p.ok||!a.ok)throw new Error('Simulation data unavailable');const pp=await p.json(),aa=await a.json();setPolicies(pp.items??[]);setActions(aa.items??[]);if(!actionId&&aa.items?.[0])setActionId(aa.items[0].actionId)}catch(e:any){setError(e.message||'Unable to load simulation')} };useEffect(()=>{void load()},[]);const run=async()=>{const policy=policies.find(p=>p.id===selectedPolicy);if(!policy||!actionId)return;const r=await fetch('/api/v1/assurance/policies/simulate',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({action_id:actionId,policy})});if(!r.ok)throw new Error('Simulation failed');setResult(await r.json())};if(error)return <div className="p-8"><div className="text-sm text-destructive">{error}</div><button onClick={()=>void load()} className="mt-4 inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-semibold"><RefreshCw className="h-3.5 w-3.5"/>Retry</button></div>;return <div className="space-y-5"><header><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Governance laboratory</div><h1 className="mt-1 text-2xl font-black tracking-tight">Policy What-If Simulator</h1><p className="mt-1 max-w-3xl text-sm text-muted-foreground">Preview approval, SLA and escalation impact before publishing a governance policy.</p></header><section className="rounded-2xl border bg-card p-5"><div className="grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end"><label className="text-xs font-semibold">Action<select value={actionId} onChange={e=>setActionId(e.target.value)} className="mt-2 w-full rounded-lg border bg-background px-3 py-2 text-sm font-normal">{actions.map(a=><option key={a.actionId} value={a.actionId}>{a.title}</option>)}</select></label><label className="text-xs font-semibold">Proposed policy<select value={selectedPolicy} onChange={e=>setSelectedPolicy(e.target.value)} className="mt-2 w-full rounded-lg border bg-background px-3 py-2 text-sm font-normal">{policies.map(p=><option key={`${p.id}-${p.version ?? 1}`} value={p.id}>{p.name} · v{p.version ?? 1}</option>)}</select></label><button type="button" onClick={()=>void run()} className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-semibold text-primary-foreground"><FlaskConical className="h-3.5 w-3.5"/> Simulate</button></div></section>{result&&<><div className="grid gap-3 md:grid-cols-3"><Metric label="Governance" value={result.impact.governanceImpact}/><Metric label="Approval delta" value={result.impact.approvalDelta>=0?`+${result.impact.approvalDelta}`:`${result.impact.approvalDelta}`}/><Metric label="SLA delta" value={`${result.impact.slaDeltaHours>=0?'+':''}${result.impact.slaDeltaHours}h`}/></div><section className="grid gap-4 md:grid-cols-2"><Compare title="Current policy" data={result.current}/><Compare title="Proposed policy" data={result.proposed}/></section><div className="flex items-center gap-2 rounded-xl border bg-card p-4 text-xs"><ShieldCheck className="h-4 w-4"/>{result.safeToPublish?'Simulation passed basic policy safety checks.':'Simulation requires review before publication.'}</div></>}</div>}
function Metric({label,value}:{label:string;value:string}){return <div className="rounded-xl border bg-card p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-xl font-black">{value}</div></div>}
function Compare({title,data}:{title:string;data:any}){return <div className="rounded-2xl border bg-card p-5"><div className="font-semibold">{title}</div><div className="mt-4 grid grid-cols-2 gap-3"><Metric label="Policy" value={`${data.policyName} v${data.policyVersion}`}/><Metric label="Approval" value={`${data.approvalRole} · ${data.approvalCount}`}/><Metric label="SLA" value={`${data.slaHours}h`}/><Metric label="Escalation" value={data.escalationTargets.join(' → ')||'None'}/></div></div>}
